# ---------------------------------------------------------------------------
# qos-pfc-decode：CONFIG 与事件形状同 qos-wire-decode，每口再声明 pfc
# （0..7 的严格递增子数组，空数组表示该口不支持 PFC）。在 qos-wire-decode
# 的四队列 SP/WRR 线速模型与 802.3x 全局 PAUSE 之上，识别目的 MAC
# 01:80:c2:00:00:01、以太类型 0x8808、操作码 0x0101 的未标记好帧为
# 802.1Qbb PFC：class-enable 置位优先级的非零 quanta 把该优先级截止时刻
# 设为 t+ceil(quanta*512000/rate)，零值清除，未置位项不变；队列暂停至
# 全局 PAUSE 与映射到该队列的全部有效 PFC 截止时刻的最大值，在发帧不
# 被抢占。PFC 帧不学习、不转发、不入队。每口八优先级各自累计实际阻塞
# 区间 pfc_duration_ns，仅由显式事件时钟结算。
# ---------------------------------------------------------------------------

QOS_PFC_CONFIG_KEYS = QOS_WIRE_CONFIG_KEYS


def validate_qos_pfc_config(config):
    """qos-pfc-decode 配置：qos-wire-decode 五键加 qos，每口再声明 pfc。"""
    if (
        not isinstance(config, dict)
        or frozenset(config) != QOS_PFC_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    delay = config["delay"]
    if not _is_int(delay) or delay <= 0:
        raise InvalidInput("bad delay")
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    age = config["age"]
    if not _is_int(age) or age <= 0:
        raise InvalidInput("age must be a positive integer")
    port_docs = config["ports"]
    if not isinstance(port_docs, list) or not port_docs:
        raise InvalidInput("ports must be a non-empty list")
    expected = (
        (PORT_KEYS_V2 - {"up"})
        | {"rates", "modes", "queue_bytes", "flow_control", "pfc"}
    )
    names = []
    caps = {}
    queues = {}
    flows = {}
    allowed_pfc = {}
    fwd_ports = []
    for port in port_docs:
        if not isinstance(port, dict) or frozenset(port) != expected:
            raise InvalidInput("bad port")
        name = port["name"]
        if not isinstance(name, str) or not name:
            raise InvalidInput("bad port name")
        names.append(name)
        rates = _validate_link_state_rates(port["rates"])
        modes = _validate_link_state_modes(port["modes"])
        caps[name] = (rates, modes)
        queue_bytes = port["queue_bytes"]
        if not _is_int(queue_bytes) or queue_bytes < 0:
            raise InvalidInput("bad queue_bytes")
        queues[name] = queue_bytes
        flow_control = port["flow_control"]
        if not isinstance(flow_control, bool):
            raise InvalidInput("bad flow_control")
        flows[name] = flow_control
        pfc = port["pfc"]
        # pfc 为 0..7 的严格递增子数组；空数组表示该口不支持 PFC
        if (
            not isinstance(pfc, list)
            or len(pfc) > PFC_PRIORITIES
            or not all(_is_int(p) and 0 <= p <= PFC_PRIORITIES - 1 for p in pfc)
            or any(pfc[i] >= pfc[i + 1] for i in range(len(pfc) - 1))
        ):
            raise InvalidInput("bad pfc")
        allowed_pfc[name] = tuple(pfc)
        fwd_ports.append(
            {
                "name": name,
                "mode": port["mode"],
                "pvid": port["pvid"],
                "allowed": port["allowed"],
                "untagged": port["untagged"],
                "up": False,
                "pfc": tuple(pfc),
            }
        )
    if len(set(names)) != len(names):
        raise InvalidInput("ports must be distinct")
    validate_forward_config_v2({"ports": fwd_ports, "age": age})
    qos_doc = config["qos"]
    if not isinstance(qos_doc, dict) or frozenset(qos_doc) != QOS_KEYS:
        raise InvalidInput("bad qos")
    mapping = qos_doc["map"]
    cap = qos_doc["cap"]
    mode = qos_doc["mode"]
    weights = qos_doc["weights"]
    drop = qos_doc["drop"]
    if (
        not isinstance(mapping, list)
        or len(mapping) != 8
        or not all(_is_int(q) and 0 <= q <= 3 for q in mapping)
    ):
        raise InvalidInput("bad qos map")
    if not _is_int(cap) or cap <= 0:
        raise InvalidInput("bad qos cap")
    if mode not in QOS_SCHED_MODES:
        raise InvalidInput("bad qos mode")
    if (
        not isinstance(weights, list)
        or len(weights) != 4
        or not all(_is_int(w) and w > 0 for w in weights)
    ):
        raise InvalidInput("bad qos weights")
    if drop not in QOS_DROP_MODES:
        raise InvalidInput("bad qos drop")
    qos = {
        "map": list(mapping),
        "cap": cap,
        "mode": mode,
        "weights": list(weights),
        "drop": drop,
    }
    return (
        fwd_ports, caps, queues, flows, qos, allowed_pfc, age, max_frame, delay
    )


def validate_qos_pfc_events(events, fwd_ports):
    """qos-pfc-decode 事件：形状口径同 qos-wire-decode（service 非法）。

    PFC 帧的长度/class-enable/保留字节合法性是运行期结果（malformed_pfc）
    而非输入错误，全量校验仅做事件外壳与帧外壳。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys not in (
            FRAME_DECODE_FRAME_KEYS,
            LINK_WIRE_LINK_EVENT_KEYS,
            LINK_WIRE_ADVANCE_EVENT_KEYS,
        ):  # service 等其他形状一律非法输入
            raise InvalidInput("bad event")
    return validate_link_flow_decode_events(events, fwd_ports)


def qos_pfc(
    fwd_ports, caps, queues, flows, qos, allowed_pfc, age, max_frame, delay,
    events, work_limit=None,
):
    """qos-pfc-decode 仿真：四队列 SP/WRR 线速模型加 802.1Qbb 优先级流控。

    状态机、协商、半双工碰撞、全局 PAUSE、入队限额与 SP/WRR 调度同
    qos_wire；另为每口维护八个优先级的 PFC 截止时刻与实际阻塞区间。
    每队列的暂停截止时刻取全局 PAUSE 与映射到本队列的有效 PFC 截止时刻
    的最大值；在发帧（无论所属队列）不被抢占。work_limit 非 None 时计费
    公式同 qos_wire（W 初值 P，每输入事件、每条 results 记录、碰撞/暂停
    后每个实际后移副本各计 1），首次超过即抛 QosPfcWorkLimit；预演与
    正式仿真共用本函数。
    """
    order = {port["name"]: i for i, port in enumerate(fwd_ports)}
    by_name = {port["name"]: port for port in fwd_ports}
    qos_map = qos["map"]
    cap = qos["cap"]
    sched_mode = qos["mode"]
    weights = qos["weights"]
    drop_mode = qos["drop"]
    weight_total = sum(weights)
    queue_limits = [-(-(cap * w) // weight_total) for w in weights]
    # 队列 -> 映射到本队列的优先级元组（截止时刻取最大值用）
    queue_prios = [
        tuple(p for p in range(PFC_PRIORITIES) if qos_map[p] == qi)
        for qi in range(4)
    ]
    committed = {name: ("down",) for name in by_name}
    pending = {}
    fdb = {}
    waitq = {
        name: [deque(), deque(), deque(), deque()] for name in by_name
    }
    head = {name: None for name in by_name}
    qframes = {name: [0, 0, 0, 0] for name in by_name}
    qbytes = {name: [0, 0, 0, 0] for name in by_name}
    txq = {name: [0, 0, 0, 0] for name in by_name}
    dropq = {name: [0, 0, 0, 0] for name in by_name}
    occupied = {name: 0 for name in by_name}
    wrr_state = {name: [3, weights[3]] for name in by_name}
    pause_until = {name: None for name in by_name}
    hold_began = {name: None for name in by_name}
    pause_ns = {name: 0 for name in by_name}
    # 每口八优先级 PFC：截止时刻、阻塞区间起点、累计实际阻塞时长
    pfc_until = {
        name: [None] * PFC_PRIORITIES for name in by_name
    }
    pfc_began = {
        name: [None] * PFC_PRIORITIES for name in by_name
    }
    pfc_ns = {name: [0] * PFC_PRIORITIES for name in by_name}
    stats = {
        name: {
            "rx_frames": 0,
            "rx_bytes": 0,
            "tx_frames": 0,
            "tx_bytes": 0,
            "collision_frames": 0,
            "collision_bytes": 0,
            "queue_full_frames": 0,
            "queue_full_bytes": 0,
            "quota_full_frames": 0,
            "quota_full_bytes": 0,
            "link_down_frames": 0,
            "link_down_bytes": 0,
            "pause_frames": 0,
            "pause_unsupported_frames": 0,
            "pause_duration_ns": 0,
            "pfc_frames": 0,
            "pfc_unsupported_frames": 0,
        }
        for name in by_name
    }
    results = []
    work = len(fwd_ports)
    if work_limit is not None and work > work_limit:
        raise QosPfcWorkLimit()

    def charge(n=1):
        nonlocal work
        work += n
        if work_limit is not None and work > work_limit:
            raise QosPfcWorkLimit()

    def is_up(name):
        return name not in pending and committed[name][0] == "up"

    def block_until(name, qi):
        """本队列暂停截止时刻：全局 PAUSE 与映射优先级有效 PFC 的最大值。"""
        until = pause_until[name]
        for p in queue_prios[qi]:
            candidate = pfc_until[name][p]
            if candidate is not None and (
                until is None or candidate > until
            ):
                until = candidate
        return until

    def accrue_hold(name, now):
        began = hold_began[name]
        until = pause_until[name]
        if until is not None and now >= until:
            if began is not None and until > began:
                pause_ns[name] += until - began
            hold_began[name] = None
            pause_until[name] = None
            return
        if began is None or now <= began:
            return
        pause_ns[name] += now - began
        hold_began[name] = now if until is not None else None

    def accrue_pfc(name, now):
        # 口径同全局 PAUSE：按墙钟逐优先级累计实际阻塞区间，到期或被清零
        # 前最后一段在每次显式时钟结算时入账
        for p in range(PFC_PRIORITIES):
            began = pfc_began[name][p]
            until = pfc_until[name][p]
            if until is not None and now >= until:
                if began is not None and until > began:
                    pfc_ns[name][p] += until - began
                pfc_began[name][p] = None
                pfc_until[name][p] = None
                continue
            if began is None or now <= began:
                continue
            pfc_ns[name][p] += now - began
            pfc_began[name][p] = now if until is not None else None

    def settle_negotiations(t):
        settled = 0
        for port in fwd_ports:
            name = port["name"]
            if name in pending and pending[name][2] <= t:
                rate, mode, _ = pending.pop(name)
                committed[name] = ("up", rate, mode)
                settled += 1
        return settled

    def pick_waiting(name, now):
        """同 qos_wire 的 sp/wrr 选取；开始时刻夹到本队列有效暂停截止。"""
        if sched_mode == "sp":
            q = next((q for q in (3, 2, 1, 0) if waitq[name][q]), None)
            if q is None:
                return False
            copy = waitq[name][q].popleft()
        else:
            q, rem = wrr_state[name]
            if not any(waitq[name][q0] for q0 in range(4)):
                return False
            while not waitq[name][q]:
                q = (q - 1) % 4
                rem = weights[q]
            copy = waitq[name][q].popleft()
            rem -= 1
            if rem == 0 or not waitq[name][q]:
                q = (q - 1) % 4
                rem = weights[q]
            wrr_state[name] = [q, rem]
        start = max(now, copy["ready"])
        until = block_until(name, copy["queue"])
        if until is not None and start < until:
            start = until
        copy["start"] = start
        copy["end"] = start + copy["duration"]
        head[name] = copy
        return True

    def settle_transmissions(t):
        while True:
            best = None
            for name in by_name:
                copy = head[name]
                if copy is not None and copy["end"] <= t:
                    cand = (copy["end"], order[name], name)
                    if best is None or cand < best:
                        best = cand
            if best is None:
                return
            name = best[2]
            copy = head[name]
            qi = copy["queue"]
            head[name] = None
            occupied[name] -= copy["bytes"]
            qframes[name][qi] -= 1
            qbytes[name][qi] -= copy["bytes"]
            txq[name][qi] += 1
            stats[name]["tx_frames"] += 1
            stats[name]["tx_bytes"] += copy["bytes"]
            results.append(
                {"t": copy["end"], "port": name,
                 "start": copy["start"], "bytes": copy["bytes"],
                 "queue": qi}
            )
            charge()
            pick_waiting(name, copy["end"])

    def settle(t):
        negotiated = settle_negotiations(t)
        settle_transmissions(t)
        for name in by_name:
            accrue_hold(name, t)
            accrue_pfc(name, t)
        return negotiated

    def apply_link(t, port, admin, peer, rates, modes):
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        before_up = port not in pending and committed[port][0] == "up"
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            applied = False
        elif target[0] == "up":
            pending[port] = (target[1], target[2], t + delay)
            applied = True
        else:
            pending.pop(port, None)
            committed[port] = target
            applied = True
        current = pending.get(port)
        if current is not None:
            state, rate, mode = "wait", None, None
            now_up = False
        else:
            now = committed[port]
            if now[0] == "up":
                state, rate, mode = "up", now[1], now[2]
                now_up = True
            else:
                state, rate, mode = now[0], None, None
                now_up = False
        left_up = before_up and not now_up
        if left_up:
            for key in [k for k, (p, _) in fdb.items() if p == port]:
                del fdb[key]
            pause_until[port] = None
            hold_began[port] = None
            pfc_until[port] = [None] * PFC_PRIORITIES
            pfc_began[port] = [None] * PFC_PRIORITIES
            dropped = []
            if head[port] is not None:
                dropped.append(head[port])
                head[port] = None
            for qi in range(4):
                dq = waitq[port][qi]
                while dq:
                    dropped.append(dq.popleft())
            for copy in dropped:
                qi = copy["queue"]
                occupied[port] -= copy["bytes"]
                qframes[port][qi] -= 1
                qbytes[port][qi] -= copy["bytes"]
                dropq[port][qi] += 1
                stats[port]["link_down_frames"] += 1
                stats[port]["link_down_bytes"] += copy["bytes"]
                results.append(
                    {
                        "t": t,
                        "port": port,
                        "start": copy.get("start", copy["ready"]),
                        "bytes": copy["bytes"],
                        "queue": qi,
                        "reason": "link_down",
                    }
                )
                charge()
        results.append(
            {"t": t, "port": port, "state": state, "rate": rate, "mode": mode}
        )
        charge()
        return state, rate, mode, applied

    def reschedule(port, ct):
        for qi in range(4):
            for copy in waitq[port][qi]:
                copy["ready"] = ct
                charge()

    def rehold(port, t):
        """PAUSE/PFC 到达或解除：未开始队头与等待副本按各自队列的有效
        暂停截止时刻（全局 PAUSE 与映射 PFC 截止的最大值）重锚。

        新锚点 = max(当前时钟/在发队头结束时刻, 本队列有效截止时刻)；
        无有效截止时锚点即 base（零值/解除可使副本提前）。重锚总是赋值，
        仅实际后移计费；队列内 FIFO 不变，跨队列顺序在选取点按 sp/wrr
        决定。返回在发队头结束时刻或 t。
        """
        inflight = head[port]
        in_flight = (
            inflight if inflight is not None and inflight["start"] <= t
            else None
        )
        base = in_flight["end"] if in_flight is not None else t

        def anchor_for(qi):
            until = block_until(port, qi)
            return base if until is None else max(base, until)

        hp = head[port]
        if hp is not None and hp["start"] > t:
            anchor = anchor_for(hp["queue"])
            if anchor > hp["start"]:
                charge()
            hp["start"] = anchor
            hp["end"] = anchor + hp["duration"]
        for qi in range(4):
            anchor = anchor_for(qi)
            for copy in waitq[port][qi]:
                if anchor > copy["ready"]:
                    charge()
                copy["ready"] = anchor
        return base

    indexed = _link_wire_indexed(fwd_ports, events)

    for _, item in indexed:
        t = item[1]
        begin = len(results)
        negotiated = settle(t)
        charge()
        kind = item[0]
        if kind == "advance":
            continue
        if kind == "link":
            _, t, port, admin, peer, rates, modes = item
            apply_link(t, port, admin, peer, rates, modes)
            continue
        (
            _,
            t,
            port_name,
            raw,
            (_, _, src, dst, tag, length, fcs, alignment),
        ) = item
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        ingress = by_name[port_name]
        inbound_wire = length + LINK_WIRE_OVERHEAD
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        # MAC 控制帧身份（PAUSE/PFC）先于半双工碰撞
        is_control_shape = (
            cls == "good"
            and tag is None
            and dst == LINK_FLOW_PAUSE_DST
            and len(raw) >= 16
            and (raw[12] << 8 | raw[13]) == LINK_FLOW_PAUSE_ETHERTYPE
        )
        opcode = (
            (raw[14] << 8) | raw[15] if is_control_shape else None
        )
        is_pfc_shape = is_control_shape and opcode == PFC_OPCODE
        hp = head[port_name]
        colliding = (
            not is_control_shape
            and hp is not None
            and is_up(port_name)
            and committed[port_name][2] == "half"
            and hp["start"] <= t < hp["end"]
        )
        if colliding:
            copy = head[port_name]
            qi = copy["queue"]
            head[port_name] = None
            occupied[port_name] -= copy["bytes"]
            qframes[port_name][qi] -= 1
            qbytes[port_name][qi] -= copy["bytes"]
            dropq[port_name][qi] += 1
            key = (copy["fvlan"], copy["fsrc"])
            if fdb.get(key) == [copy["fing"], copy["fseen"]]:
                del fdb[key]
            stats[port_name]["collision_frames"] += 2
            stats[port_name]["collision_bytes"] += (
                inbound_wire + copy["bytes"]
            )
            results.append(
                {
                    "t": t,
                    "port": port_name,
                    "start": copy["start"],
                    "bytes": copy["bytes"],
                    "queue": qi,
                    "inbound": inbound_wire,
                    "reason": "collision",
                }
            )
            charge()
            reschedule(port_name, t)
            pick_waiting(port_name, t)
            continue
        stats[port_name]["rx_frames"] += 1
        stats[port_name]["rx_bytes"] += inbound_wire
        if cls != "good":
            results.append(
                {"t": t, "class": cls, "action": "drop", "ports": []}
            )
            charge()
            continue
        if is_pfc_shape:
            # 802.1Qbb PFC 帧体：恰 64 字节；class-enable 两字节、八优先级
            # 各两字节 quanta（偏移 18..33），其余 26 字节保留全零
            class_enable = (raw[16] << 8) | raw[17]
            quanta = [
                (raw[18 + 2 * p] << 8) | raw[18 + 2 * p + 1]
                for p in range(PFC_PRIORITIES)
            ]
            reserved_ok = (
                length == FRAME_CHECK_RUNT_LENGTH
                and not any(raw[34:length - 4])
            )
            if not reserved_ok:
                results.append(
                    {"t": t, "port": port_name,
                     "action": "malformed_pfc"}
                )
                charge()
                continue
            stats[port_name]["pfc_frames"] += 1
            enabled = [
                p for p in range(PFC_PRIORITIES)
                if (class_enable >> (PFC_PRIORITIES - 1 - p)) & 1
            ]
            allowed = allowed_pfc[port_name]
            if not (
                is_up(port_name)
                and committed[port_name][2] == "full"
                and all(p in allowed for p in enabled)
            ):
                stats[port_name]["pfc_unsupported_frames"] += 1
                results.append(
                    {"t": t, "port": port_name,
                     "action": "pfc_unsupported"}
                )
                charge()
                continue
            rate = committed[port_name][1]
            inflight = head[port_name]
            in_flight = (
                inflight if inflight is not None
                and inflight["start"] <= t
                else None
            )
            entries = []
            for p in enabled:
                q = quanta[p]
                if q == 0:
                    # 零值清除该优先级截止时刻；settle 已把截至 t 的阻塞
                    # 时长入账
                    pfc_until[port_name][p] = None
                    pfc_began[port_name][p] = None
                    entries.append(
                        {"priority": p, "quanta": 0, "until": None}
                    )
                    continue
                until = t + (
                    q * LINK_FLOW_PAUSE_QUANTA_TICKS + rate - 1
                ) // rate
                pfc_until[port_name][p] = until
                qi = qos_map[p]
                base = (
                    in_flight["end"]
                    if in_flight is not None and in_flight["queue"] == qi
                    else t
                )
                pfc_began[port_name][p] = base if until > base else None
                entries.append(
                    {"priority": p, "quanta": q, "until": until}
                )
            rehold(port_name, t)
            results.append(
                {"t": t, "port": port_name, "action": "pfc",
                 "priorities": entries}
            )
            charge()
            continue
        if is_control_shape:
            opcode_ctrl = opcode
            reserved_ok = (
                length == FRAME_CHECK_RUNT_LENGTH
                and len(raw) >= 60
                and not any(raw[18:length - 4])
            )
            if (
                length != FRAME_CHECK_RUNT_LENGTH
                or opcode_ctrl != LINK_FLOW_PAUSE_OPCODE
                or not reserved_ok
            ):
                results.append(
                    {"t": t, "port": port_name,
                     "action": "malformed_pause"}
                )
                charge()
                continue
            stats[port_name]["pause_frames"] += 1
            pause_quanta = (raw[16] << 8) | raw[17]
            if not (
                is_up(port_name)
                and committed[port_name][2] == "full"
                and flows[port_name]
            ):
                stats[port_name]["pause_unsupported_frames"] += 1
                results.append(
                    {"t": t, "port": port_name,
                     "action": "pause_unsupported"}
                )
                charge()
                continue
            if pause_quanta == 0:
                pause_until[port_name] = None
                hold_began[port_name] = None
                base = rehold(port_name, t)
                results.append(
                    {"t": t, "port": port_name, "action": "pause",
                     "quanta": 0, "until": None}
                )
                charge()
                continue
            rate = committed[port_name][1]
            until = t + (
                pause_quanta * LINK_FLOW_PAUSE_QUANTA_TICKS + rate - 1
            ) // rate
            pause_until[port_name] = until
            base = rehold(port_name, t)
            hold_began[port_name] = base if until > base else None
            results.append(
                {"t": t, "port": port_name, "action": "pause",
                 "quanta": pause_quanta, "until": until}
            )
            charge()
            continue
        if tag is None:
            vlan = ingress["pvid"]
            rejected = False
            tagged_ingress = False
        else:
            vlan = tag
            tagged_ingress = True
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:
            results.append(
                {"t": t, "class": cls, "action": "drop", "ports": []}
            )
            charge()
            continue
        egress = []
        action = "drop"
        if is_up(port_name):
            fdb[(vlan, src)] = [port_name, t]
            hit = None if dst == BROADCAST_MAC else fdb.get((vlan, dst))
            if hit is not None and hit[0] != port_name:
                target_name = hit[0]
                if (
                    is_up(target_name)
                    and vlan in by_name[target_name]["allowed"]
                ):
                    egress = [target_name]
                    action = "unicast"
            elif hit is None:
                egress = [
                    port["name"]
                    for port in fwd_ports
                    if vlan in port["allowed"]
                    and is_up(port["name"])
                    and port["name"] != port_name
                ]
                if egress:
                    action = "flood"
        out_ports = []
        copies = []
        for name in egress:
            out_vlan = None if vlan in by_name[name]["untagged"] else vlan
            out_ports.append({"name": name, "vlan": out_vlan})
            frame_len = length + (
                4 if not tagged_ingress and out_vlan is not None else
                -4 if tagged_ingress and out_vlan is None else 0
            )
            wire_bytes = frame_len + LINK_WIRE_OVERHEAD
            copies.append((name, out_vlan, wire_bytes))
        results.append(
            {"t": t, "class": cls, "action": action, "ports": out_ports}
        )
        charge()
        qi = qos_map[_qos_wire_priority(raw)]
        qlimit = cap if drop_mode == "tail" else queue_limits[qi]
        for name, out_vlan, wire_bytes in copies:
            egr_rate = committed[name][1]
            duration = (wire_bytes * 8000 + egr_rate - 1) // egr_rate
            if occupied[name] + wire_bytes > queues[name]:
                stats[name]["queue_full_frames"] += 1
                stats[name]["queue_full_bytes"] += wire_bytes
                dropq[name][qi] += 1
                results.append(
                    {
                        "t": t,
                        "port": name,
                        "vlan": out_vlan,
                        "bytes": wire_bytes,
                        "queue": qi,
                        "reason": "queue_full",
                    }
                )
                charge()
                continue
            if qbytes[name][qi] + wire_bytes > qlimit:
                stats[name]["quota_full_frames"] += 1
                stats[name]["quota_full_bytes"] += wire_bytes
                dropq[name][qi] += 1
                results.append(
                    {
                        "t": t,
                        "port": name,
                        "vlan": out_vlan,
                        "bytes": wire_bytes,
                        "queue": qi,
                        "reason": "quota_full",
                    }
                )
                charge()
                continue
            hp = head[name]
            ready = t if hp is None else max(t, hp["end"])
            same_tail = waitq[name][qi][-1] if waitq[name][qi] else None
            if same_tail is not None:
                ready = max(ready, same_tail["ready"] + same_tail["duration"])
            until = block_until(name, qi)
            if until is not None and ready < until:
                ready = until
            copy = {
                "egress": name,
                "vlan": out_vlan,
                "bytes": wire_bytes,
                "duration": duration,
                "ready": ready,
                "start": None,
                "end": 0,
                "queue": qi,
                "fvlan": vlan,
                "fsrc": src,
                "fing": port_name,
                "fseen": t,
            }
            waitq[name][qi].append(copy)
            qframes[name][qi] += 1
            qbytes[name][qi] += wire_bytes
            occupied[name] += wire_bytes
            results.append(
                {"t": t, "port": name, "vlan": out_vlan,
                 "bytes": wire_bytes, "queue": qi}
            )
            charge()
            if head[name] is None:
                pick_waiting(name, t)
    return {
        "results": results,
        "ports": [
            {
                "name": name,
                "queues": [
                    {
                        "frames": qframes[name][qi],
                        "bytes": qbytes[name][qi],
                        "sent": txq[name][qi],
                        "dropped": dropq[name][qi],
                    }
                    for qi in range(4)
                ],
                "rx_frames": stats[name]["rx_frames"],
                "rx_bytes": stats[name]["rx_bytes"],
                "tx_frames": stats[name]["tx_frames"],
                "tx_bytes": stats[name]["tx_bytes"],
                "collision_frames": stats[name]["collision_frames"],
                "collision_bytes": stats[name]["collision_bytes"],
                "queue_full_frames": stats[name]["queue_full_frames"],
                "queue_full_bytes": stats[name]["queue_full_bytes"],
                "quota_full_frames": stats[name]["quota_full_frames"],
                "quota_full_bytes": stats[name]["quota_full_bytes"],
                "link_down_frames": stats[name]["link_down_frames"],
                "link_down_bytes": stats[name]["link_down_bytes"],
                "pause_frames": stats[name]["pause_frames"],
                "pause_unsupported_frames":
                    stats[name]["pause_unsupported_frames"],
                "pause_duration_ns": pause_ns[name],
                "pfc_frames": stats[name]["pfc_frames"],
                "pfc_unsupported_frames":
                    stats[name]["pfc_unsupported_frames"],
                "pfc_duration_ns": list(pfc_ns[name]),
            }
            for name in by_name
        ],
    }


def qos_pfc_work(
    fwd_ports, caps, queues, flows, qos, allowed_pfc, age, max_frame, delay,
    events, limit,
):
    """qos-pfc-decode 工作量预演：独立状态跑同一仿真，无副作用、不产出。

    与 qos_pfc 同一计费公式（W 初值 P，每输入事件、每条 results 记录、
    碰撞/暂停后每个实际后移副本各计 1），等于上限合法，首次超过即抛
    QosPfcWorkLimit。
    """
    qos_pfc(
        fwd_ports, caps, queues, flows, qos, allowed_pfc, age, max_frame,
        delay, events, work_limit=limit,
    )

toolUseResult.newString:
    qos_wire(
        fwd_ports, caps, queues, flows, qos, age, max_frame, delay, events,
        work_limit=limit,
    )


# ---------------------------------------------------------------------------
# qos-pfc-decode：CONFIG 与事件形状同 qos-wire-decode，每口再声明 pfc
# （0..7 的严格递增子数组，空数组表示该口不支持 PFC）。在 qos-wire-decode
# 的四队列 SP/WRR 线速模型与 802.3x 全局 PAUSE 之上，识别目的 MAC
# 01:80:c2:00:00:01、以太类型 0x8808、操作码 0x0101 的未标记好帧为
# 802.1Qbb PFC：class-enable 置位优先级的非零 quanta 把该优先级截止时刻
# 设为 t+ceil(quanta*512000/rate)，零值清除，未置位项不变；队列暂停至
# 全局 PAUSE 与映射到该队列的全部有效 PFC 截止时刻的最大值，在发帧不
# 被抢占。PFC 帧不学习、不转发、不入队。每口八优先级各自累计实际阻塞
# 区间 pfc_duration_ns，仅由显式事件时钟结算。
# ---------------------------------------------------------------------------

QOS_PFC_CONFIG_KEYS = QOS_WIRE_CONFIG_KEYS


def validate_qos_pfc_config(config):
    """qos-pfc-decode 配置：qos-wire-decode 五键加 qos，每口再声明 pfc。"""
    if (
        not isinstance(config, dict)
        or frozenset(config) != QOS_PFC_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    delay = config["delay"]
    if not _is_int(delay) or delay <= 0:
        raise InvalidInput("bad delay")
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    age = config["age"]
    if not _is_int(age) or age <= 0:
        raise InvalidInput("age must be a positive integer")
    port_docs = config["ports"]
    if not isinstance(port_docs, list) or not port_docs:
        raise InvalidInput("ports must be a non-empty list")
    expected = (
        (PORT_KEYS_V2 - {"up"})
        | {"rates", "modes", "queue_bytes", "flow_control", "pfc"}
    )
    names = []
    caps = {}
    queues = {}
    flows = {}
    allowed_pfc = {}
    fwd_ports = []
    for port in port_docs:
        if not isinstance(port, dict) or frozenset(port) != expected:
            raise InvalidInput("bad port")
        name = port["name"]
        if not isinstance(name, str) or not name:
            raise InvalidInput("bad port name")
        names.append(name)
        rates = _validate_link_state_rates(port["rates"])
        modes = _validate_link_state_modes(port["modes"])
        caps[name] = (rates, modes)
        queue_bytes = port["queue_bytes"]
        if not _is_int(queue_bytes) or queue_bytes < 0:
            raise InvalidInput("bad queue_bytes")
        queues[name] = queue_bytes
        flow_control = port["flow_control"]
        if not isinstance(flow_control, bool):
            raise InvalidInput("bad flow_control")
        flows[name] = flow_control
        pfc = port["pfc"]
        # pfc 为 0..7 的严格递增子数组；空数组表示该口不支持 PFC
        if (
            not isinstance(pfc, list)
            or len(pfc) > PFC_PRIORITIES
            or not all(_is_int(p) and 0 <= p <= PFC_PRIORITIES - 1 for p in pfc)
            or any(pfc[i] >= pfc[i + 1] for i in range(len(pfc) - 1))
        ):
            raise InvalidInput("bad pfc")
        allowed_pfc[name] = tuple(pfc)
        fwd_ports.append(
            {
                "name": name,
                "mode": port["mode"],
                "pvid": port["pvid"],
                "allowed": port["allowed"],
                "untagged": port["untagged"],
                "up": False,
                "pfc": tuple(pfc),
            }
        )
    if len(set(names)) != len(names):
        raise InvalidInput("ports must be distinct")
    validate_forward_config_v2({"ports": fwd_ports, "age": age})
    qos_doc = config["qos"]
    if not isinstance(qos_doc, dict) or frozenset(qos_doc) != QOS_KEYS:
        raise InvalidInput("bad qos")
    mapping = qos_doc["map"]
    cap = qos_doc["cap"]
    mode = qos_doc["mode"]
    weights = qos_doc["weights"]
    drop = qos_doc["drop"]
    if (
        not isinstance(mapping, list)
        or len(mapping) != 8
        or not all(_is_int(q) and 0 <= q <= 3 for q in mapping)
    ):
        raise InvalidInput("bad qos map")
    if not _is_int(cap) or cap <= 0:
        raise InvalidInput("bad qos cap")
    if mode not in QOS_SCHED_MODES:
        raise InvalidInput("bad qos mode")
    if (
        not isinstance(weights, list)
        or len(weights) != 4
        or not all(_is_int(w) and w > 0 for w in weights)
    ):
        raise InvalidInput("bad qos weights")
    if drop not in QOS_DROP_MODES:
        raise InvalidInput("bad qos drop")
    qos = {
        "map": list(mapping),
        "cap": cap,
        "mode": mode,
        "weights": list(weights),
        "drop": drop,
    }
    return (
        fwd_ports, caps, queues, flows, qos, allowed_pfc, age, max_frame, delay
    )


def validate_qos_pfc_events(events, fwd_ports):
    """qos-pfc-decode 事件：形状口径同 qos-wire-decode（service 非法）。

    PFC 帧的长度/class-enable/保留字节合法性是运行期结果（malformed_pfc）
    而非输入错误，全量校验仅做事件外壳与帧外壳。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys not in (
            FRAME_DECODE_FRAME_KEYS,
            LINK_WIRE_LINK_EVENT_KEYS,
            LINK_WIRE_ADVANCE_EVENT_KEYS,
        ):  # service 等其他形状一律非法输入
            raise InvalidInput("bad event")
    return validate_link_flow_decode_events(events, fwd_ports)


def qos_pfc(
    fwd_ports, caps, queues, flows, qos, allowed_pfc, age, max_frame, delay,
    events, work_limit=None,
):
    """qos-pfc-decode 仿真：四队列 SP/WRR 线速模型加 802.1Qbb 优先级流控。

    状态机、协商、半双工碰撞、全局 PAUSE、入队限额与 SP/WRR 调度同
    qos_wire；另为每口维护八个优先级的 PFC 截止时刻与实际阻塞区间。
    每队列的暂停截止时刻取全局 PAUSE 与映射到本队列的有效 PFC 截止时刻
    的最大值；在发帧（无论所属队列）不被抢占。work_limit 非 None 时计费
    公式同 qos_wire（W 初值 P，每输入事件、每条 results 记录、碰撞/暂停
    后每个实际后移副本各计 1），首次超过即抛 QosPfcWorkLimit；预演与
    正式仿真共用本函数。
    """
    order = {port["name"]: i for i, port in enumerate(fwd_ports)}
    by_name = {port["name"]: port for port in fwd_ports}
    qos_map = qos["map"]
    cap = qos["cap"]
    sched_mode = qos["mode"]
    weights = qos["weights"]
    drop_mode = qos["drop"]
    weight_total = sum(weights)
    queue_limits = [-(-(cap * w) // weight_total) for w in weights]
    # 队列 -> 映射到本队列的优先级元组（截止时刻取最大值用）
    queue_prios = [
        tuple(p for p in range(PFC_PRIORITIES) if qos_map[p] == qi)
        for qi in range(4)
    ]
    committed = {name: ("down",) for name in by_name}
    pending = {}
    fdb = {}
    waitq = {
        name: [deque(), deque(), deque(), deque()] for name in by_name
    }
    head = {name: None for name in by_name}
    qframes = {name: [0, 0, 0, 0] for name in by_name}
    qbytes = {name: [0, 0, 0, 0] for name in by_name}
    txq = {name: [0, 0, 0, 0] for name in by_name}
    dropq = {name: [0, 0, 0, 0] for name in by_name}
    occupied = {name: 0 for name in by_name}
    wrr_state = {name: [3, weights[3]] for name in by_name}
    pause_until = {name: None for name in by_name}
    hold_began = {name: None for name in by_name}
    pause_ns = {name: 0 for name in by_name}
    # 每口八优先级 PFC：截止时刻、阻塞区间起点、累计实际阻塞时长
    pfc_until = {
        name: [None] * PFC_PRIORITIES for name in by_name
    }
    pfc_began = {
        name: [None] * PFC_PRIORITIES for name in by_name
    }
    pfc_ns = {name: [0] * PFC_PRIORITIES for name in by_name}
    stats = {
        name: {
            "rx_frames": 0,
            "rx_bytes": 0,
            "tx_frames": 0,
            "tx_bytes": 0,
            "collision_frames": 0,
            "collision_bytes": 0,
            "queue_full_frames": 0,
            "queue_full_bytes": 0,
            "quota_full_frames": 0,
            "quota_full_bytes": 0,
            "link_down_frames": 0,
            "link_down_bytes": 0,
            "pause_frames": 0,
            "pause_unsupported_frames": 0,
            "pause_duration_ns": 0,
            "pfc_frames": 0,
            "pfc_unsupported_frames": 0,
        }
        for name in by_name
    }
    results = []
    work = len(fwd_ports)
    if work_limit is not None and work > work_limit:
        raise QosPfcWorkLimit()

    def charge(n=1):
        nonlocal work
        work += n
        if work_limit is not None and work > work_limit:
            raise QosPfcWorkLimit()

    def is_up(name):
        return name not in pending and committed[name][0] == "up"

    def block_until(name, qi):
        """本队列暂停截止时刻：全局 PAUSE 与映射优先级有效 PFC 的最大值。"""
        until = pause_until[name]
        for p in queue_prios[qi]:
            candidate = pfc_until[name][p]
            if candidate is not None and (
                until is None or candidate > until
            ):
                until = candidate
        return until

    def accrue_hold(name, now):
        began = hold_began[name]
        until = pause_until[name]
        if until is not None and now >= until:
            if began is not None and until > began:
                pause_ns[name] += until - began
            hold_began[name] = None
            pause_until[name] = None
            return
        if began is None or now <= began:
            return
        pause_ns[name] += now - began
        hold_began[name] = now if until is not None else None

    def accrue_pfc(name, now):
        # 口径同全局 PAUSE：按墙钟逐优先级累计实际阻塞区间，到期或被清零
        # 前最后一段在每次显式时钟结算时入账
        for p in range(PFC_PRIORITIES):
            began = pfc_began[name][p]
            until = pfc_until[name][p]
            if until is not None and now >= until:
                if began is not None and until > began:
                    pfc_ns[name][p] += until - began
                pfc_began[name][p] = None
                pfc_until[name][p] = None
                continue
            if began is None or now <= began:
                continue
            pfc_ns[name][p] += now - began
            pfc_began[name][p] = now if until is not None else None

    def settle_negotiations(t):
        settled = 0
        for port in fwd_ports:
            name = port["name"]
            if name in pending and pending[name][2] <= t:
                rate, mode, _ = pending.pop(name)
                committed[name] = ("up", rate, mode)
                settled += 1
        return settled

    def pick_waiting(name, now):
        """同 qos_wire 的 sp/wrr 选取；开始时刻夹到本队列有效暂停截止。"""
        if sched_mode == "sp":
            q = next((q for q in (3, 2, 1, 0) if waitq[name][q]), None)
            if q is None:
                return False
            copy = waitq[name][q].popleft()
        else:
            q, rem = wrr_state[name]
            if not any(waitq[name][q0] for q0 in range(4)):
                return False
            while not waitq[name][q]:
                q = (q - 1) % 4
                rem = weights[q]
            copy = waitq[name][q].popleft()
            rem -= 1
            if rem == 0 or not waitq[name][q]:
                q = (q - 1) % 4
                rem = weights[q]
            wrr_state[name] = [q, rem]
        start = max(now, copy["ready"])
        until = block_until(name, copy["queue"])
        if until is not None and start < until:
            start = until
        copy["start"] = start
        copy["end"] = start + copy["duration"]
        head[name] = copy
        return True

    def settle_transmissions(t):
        while True:
            best = None
            for name in by_name:
                copy = head[name]
                if copy is not None and copy["end"] <= t:
                    cand = (copy["end"], order[name], name)
                    if best is None or cand < best:
                        best = cand
            if best is None:
                return
            name = best[2]
            copy = head[name]
            qi = copy["queue"]
            head[name] = None
            occupied[name] -= copy["bytes"]
            qframes[name][qi] -= 1
            qbytes[name][qi] -= copy["bytes"]
            txq[name][qi] += 1
            stats[name]["tx_frames"] += 1
            stats[name]["tx_bytes"] += copy["bytes"]
            results.append(
                {"t": copy["end"], "port": name,
                 "start": copy["start"], "bytes": copy["bytes"],
                 "queue": qi}
            )
            charge()
            pick_waiting(name, copy["end"])

    def settle(t):
        negotiated = settle_negotiations(t)
        settle_transmissions(t)
        for name in by_name:
            accrue_hold(name, t)
            accrue_pfc(name, t)
        return negotiated

    def apply_link(t, port, admin, peer, rates, modes):
        if not admin or not peer:
            target = ("down",)
        else:
            local_rates, local_modes = caps[port]
            common_rates = [r for r in local_rates if r in rates]
            common_modes = [m for m in local_modes if m in modes]
            if not common_rates or not common_modes:
                target = ("bad",)
            else:
                target = (
                    "up",
                    max(common_rates),
                    "full" if "full" in common_modes else "half",
                )
        before_up = port not in pending and committed[port][0] == "up"
        current = pending.get(port)
        effective = (
            ("up", current[0], current[1])
            if current is not None
            else committed[port]
        )
        if target == effective:
            applied = False
        elif target[0] == "up":
            pending[port] = (target[1], target[2], t + delay)
            applied = True
        else:
            pending.pop(port, None)
            committed[port] = target
            applied = True
        current = pending.get(port)
        if current is not None:
            state, rate, mode = "wait", None, None
            now_up = False
        else:
            now = committed[port]
            if now[0] == "up":
                state, rate, mode = "up", now[1], now[2]
                now_up = True
            else:
                state, rate, mode = now[0], None, None
                now_up = False
        left_up = before_up and not now_up
        if left_up:
            for key in [k for k, (p, _) in fdb.items() if p == port]:
                del fdb[key]
            pause_until[port] = None
            hold_began[port] = None
            pfc_until[port] = [None] * PFC_PRIORITIES
            pfc_began[port] = [None] * PFC_PRIORITIES
            dropped = []
            if head[port] is not None:
                dropped.append(head[port])
                head[port] = None
            for qi in range(4):
                dq = waitq[port][qi]
                while dq:
                    dropped.append(dq.popleft())
            for copy in dropped:
                qi = copy["queue"]
                occupied[port] -= copy["bytes"]
                qframes[port][qi] -= 1
                qbytes[port][qi] -= copy["bytes"]
                dropq[port][qi] += 1
                stats[port]["link_down_frames"] += 1
                stats[port]["link_down_bytes"] += copy["bytes"]
                results.append(
                    {
                        "t": t,
                        "port": port,
                        "start": copy.get("start", copy["ready"]),
                        "bytes": copy["bytes"],
                        "queue": qi,
                        "reason": "link_down",
                    }
                )
                charge()
        results.append(
            {"t": t, "port": port, "state": state, "rate": rate, "mode": mode}
        )
        charge()
        return state, rate, mode, applied

    def reschedule(port, ct):
        for qi in range(4):
            for copy in waitq[port][qi]:
                copy["ready"] = ct
                charge()

    def rehold(port, t):
        """PAUSE/PFC 到达或解除：未开始队头与等待副本按各自队列的有效
        暂停截止时刻（全局 PAUSE 与映射 PFC 截止的最大值）重锚。

        新锚点 = max(当前时钟/在发队头结束时刻, 本队列有效截止时刻)；
        无有效截止时锚点即 base（零值/解除可使副本提前）。重锚总是赋值，
        仅实际后移计费；队列内 FIFO 不变，跨队列顺序在选取点按 sp/wrr
        决定。返回在发队头结束时刻或 t。
        """
        inflight = head[port]
        in_flight = (
            inflight if inflight is not None and inflight["start"] <= t
            else None
        )
        base = in_flight["end"] if in_flight is not None else t

        def anchor_for(qi):
            until = block_until(port, qi)
            return base if until is None else max(base, until)

        hp = head[port]
        if hp is not None and hp["start"] > t:
            anchor = anchor_for(hp["queue"])
            if anchor > hp["start"]:
                charge()
            hp["start"] = anchor
            hp["end"] = anchor + hp["duration"]
        for qi in range(4):
            anchor = anchor_for(qi)
            for copy in waitq[port][qi]:
                if anchor > copy["ready"]:
                    charge()
                copy["ready"] = anchor
        return base

    indexed = _link_wire_indexed(fwd_ports, events)

    for _, item in indexed:
        t = item[1]
        begin = len(results)
        negotiated = settle(t)
        charge()
        kind = item[0]
        if kind == "advance":
            continue
        if kind == "link":
            _, t, port, admin, peer, rates, modes = item
            apply_link(t, port, admin, peer, rates, modes)
            continue
        (
            _,
            t,
            port_name,
            raw,
            (_, _, src, dst, tag, length, fcs, alignment),
        ) = item
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        ingress = by_name[port_name]
        inbound_wire = length + LINK_WIRE_OVERHEAD
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        # MAC 控制帧身份（PAUSE/PFC）先于半双工碰撞
        is_control_shape = (
            cls == "good"
            and tag is None
            and dst == LINK_FLOW_PAUSE_DST
            and len(raw) >= 16
            and (raw[12] << 8 | raw[13]) == LINK_FLOW_PAUSE_ETHERTYPE
        )
        opcode = (
            (raw[14] << 8) | raw[15] if is_control_shape else None
        )
        is_pfc_shape = is_control_shape and opcode == PFC_OPCODE
        hp = head[port_name]
        colliding = (
            not is_control_shape
            and hp is not None
            and is_up(port_name)
            and committed[port_name][2] == "half"
            and hp["start"] <= t < hp["end"]
        )
        if colliding:
            copy = head[port_name]
            qi = copy["queue"]
            head[port_name] = None
            occupied[port_name] -= copy["bytes"]
            qframes[port_name][qi] -= 1
            qbytes[port_name][qi] -= copy["bytes"]
            dropq[port_name][qi] += 1
            key = (copy["fvlan"], copy["fsrc"])
            if fdb.get(key) == [copy["fing"], copy["fseen"]]:
                del fdb[key]
            stats[port_name]["collision_frames"] += 2
            stats[port_name]["collision_bytes"] += (
                inbound_wire + copy["bytes"]
            )
            results.append(
                {
                    "t": t,
                    "port": port_name,
                    "start": copy["start"],
                    "bytes": copy["bytes"],
                    "queue": qi,
                    "inbound": inbound_wire,
                    "reason": "collision",
                }
            )
            charge()
            reschedule(port_name, t)
            pick_waiting(port_name, t)
            continue
        stats[port_name]["rx_frames"] += 1
        stats[port_name]["rx_bytes"] += inbound_wire
        if cls != "good":
            results.append(
                {"t": t, "class": cls, "action": "drop", "ports": []}
            )
            charge()
            continue
        if is_pfc_shape:
            # 802.1Qbb PFC 帧体：恰 64 字节；class-enable 两字节、八优先级
            # 各两字节 quanta（偏移 18..33），其余 26 字节保留全零
            class_enable = (raw[16] << 8) | raw[17]
            quanta = [
                (raw[18 + 2 * p] << 8) | raw[18 + 2 * p + 1]
                for p in range(PFC_PRIORITIES)
            ]
            reserved_ok = (
                length == FRAME_CHECK_RUNT_LENGTH
                and not any(raw[34:length - 4])
            )
            if not reserved_ok:
                results.append(
                    {"t": t, "port": port_name,
                     "action": "malformed_pfc"}
                )
                charge()
                continue
            stats[port_name]["pfc_frames"] += 1
            enabled = [
                p for p in range(PFC_PRIORITIES)
                if (class_enable >> (PFC_PRIORITIES - 1 - p)) & 1
            ]
            allowed = allowed_pfc[port_name]
            if not (
                is_up(port_name)
                and committed[port_name][2] == "full"
                and all(p in allowed for p in enabled)
            ):
                stats[port_name]["pfc_unsupported_frames"] += 1
                results.append(
                    {"t": t, "port": port_name,
                     "action": "pfc_unsupported"}
                )
                charge()
                continue
            rate = committed[port_name][1]
            inflight = head[port_name]
            in_flight = (
                inflight if inflight is not None
                and inflight["start"] <= t
                else None
            )
            entries = []
            for p in enabled:
                q = quanta[p]
                if q == 0:
                    # 零值清除该优先级截止时刻；settle 已把截至 t 的阻塞
                    # 时长入账
                    pfc_until[port_name][p] = None
                    pfc_began[port_name][p] = None
                    entries.append(
                        {"priority": p, "quanta": 0, "until": None}
                    )
                    continue
                until = t + (
                    q * LINK_FLOW_PAUSE_QUANTA_TICKS + rate - 1
                ) // rate
                pfc_until[port_name][p] = until
                qi = qos_map[p]
                base = (
                    in_flight["end"]
                    if in_flight is not None and in_flight["queue"] == qi
                    else t
                )
                pfc_began[port_name][p] = base if until > base else None
                entries.append(
                    {"priority": p, "quanta": q, "until": until}
                )
            rehold(port_name, t)
            results.append(
                {"t": t, "port": port_name, "action": "pfc",
                 "priorities": entries}
            )
            charge()
            continue
        if is_control_shape:
            opcode_ctrl = opcode
            reserved_ok = (
                length == FRAME_CHECK_RUNT_LENGTH
                and len(raw) >= 60
                and not any(raw[18:length - 4])
            )
            if (
                length != FRAME_CHECK_RUNT_LENGTH
                or opcode_ctrl != LINK_FLOW_PAUSE_OPCODE
                or not reserved_ok
            ):
                results.append(
                    {"t": t, "port": port_name,
                     "action": "malformed_pause"}
                )
                charge()
                continue
            stats[port_name]["pause_frames"] += 1
            pause_quanta = (raw[16] << 8) | raw[17]
            if not (
                is_up(port_name)
                and committed[port_name][2] == "full"
                and flows[port_name]
            ):
                stats[port_name]["pause_unsupported_frames"] += 1
                results.append(
                    {"t": t, "port": port_name,
                     "action": "pause_unsupported"}
                )
                charge()
                continue
            if pause_quanta == 0:
                pause_until[port_name] = None
                hold_began[port_name] = None
                base = rehold(port_name, t)
                results.append(
                    {"t": t, "port": port_name, "action": "pause",
                     "quanta": 0, "until": None}
                )
                charge()
                continue
            rate = committed[port_name][1]
            until = t + (
                pause_quanta * LINK_FLOW_PAUSE_QUANTA_TICKS + rate - 1
            ) // rate
            pause_until[port_name] = until
            base = rehold(port_name, t)
            hold_began[port_name] = base if until > base else None
            results.append(
                {"t": t, "port": port_name, "action": "pause",
                 "quanta": pause_quanta, "until": until}
            )
            charge()
            continue
        if tag is None:
            vlan = ingress["pvid"]
            rejected = False
            tagged_ingress = False
        else:
            vlan = tag
            tagged_ingress = True
            rejected = (
                ingress["mode"] == "access" or vlan not in ingress["allowed"]
            )
        if rejected:
            results.append(
                {"t": t, "class": cls, "action": "drop", "ports": []}
            )
            charge()
            continue
        egress = []
        action = "drop"
        if is_up(port_name):
            fdb[(vlan, src)] = [port_name, t]
            hit = None if dst == BROADCAST_MAC else fdb.get((vlan, dst))
            if hit is not None and hit[0] != port_name:
                target_name = hit[0]
                if (
                    is_up(target_name)
                    and vlan in by_name[target_name]["allowed"]
                ):
                    egress = [target_name]
                    action = "unicast"
            elif hit is None:
                egress = [
                    port["name"]
                    for port in fwd_ports
                    if vlan in port["allowed"]
                    and is_up(port["name"])
                    and port["name"] != port_name
                ]
                if egress:
                    action = "flood"
        out_ports = []
        copies = []
        for name in egress:
            out_vlan = None if vlan in by_name[name]["untagged"] else vlan
            out_ports.append({"name": name, "vlan": out_vlan})
            frame_len = length + (
                4 if not tagged_ingress and out_vlan is not None else
                -4 if tagged_ingress and out_vlan is None else 0
            )
            wire_bytes = frame_len + LINK_WIRE_OVERHEAD
            copies.append((name, out_vlan, wire_bytes))
        results.append(
            {"t": t, "class": cls, "action": action, "ports": out_ports}
        )
        charge()
        qi = qos_map[_qos_wire_priority(raw)]
        qlimit = cap if drop_mode == "tail" else queue_limits[qi]
        for name, out_vlan, wire_bytes in copies:
            egr_rate = committed[name][1]
            duration = (wire_bytes * 8000 + egr_rate - 1) // egr_rate
            if occupied[name] + wire_bytes > queues[name]:
                stats[name]["queue_full_frames"] += 1
                stats[name]["queue_full_bytes"] += wire_bytes
                dropq[name][qi] += 1
                results.append(
                    {
                        "t": t,
                        "port": name,
                        "vlan": out_vlan,
                        "bytes": wire_bytes,
                        "queue": qi,
                        "reason": "queue_full",
                    }
                )
                charge()
                continue
            if qbytes[name][qi] + wire_bytes > qlimit:
                stats[name]["quota_full_frames"] += 1
                stats[name]["quota_full_bytes"] += wire_bytes
                dropq[name][qi] += 1
                results.append(
                    {
                        "t": t,
                        "port": name,
                        "vlan": out_vlan,
                        "bytes": wire_bytes,
                        "queue": qi,
                        "reason": "quota_full",
                    }
                )
                charge()
                continue
            hp = head[name]
            ready = t if hp is None else max(t, hp["end"])
            same_tail = waitq[name][qi][-1] if waitq[name][qi] else None
            if same_tail is not None:
                ready = max(ready, same_tail["ready"] + same_tail["duration"])
            until = block_until(name, qi)
            if until is not None and ready < until:
                ready = until
            copy = {
                "egress": name,
                "vlan": out_vlan,
                "bytes": wire_bytes,
                "duration": duration,
                "ready": ready,
                "start": None,
                "end": 0,
                "queue": qi,
                "fvlan": vlan,
                "fsrc": src,
                "fing": port_name,
                "fseen": t,
            }
            waitq[name][qi].append(copy)
            qframes[name][qi] += 1
            qbytes[name][qi] += wire_bytes
            occupied[name] += wire_bytes
            results.append(
                {"t": t, "port": name, "vlan": out_vlan,
                 "bytes": wire_bytes, "queue": qi}
            )
            charge()
            if head[name] is None:
                pick_waiting(name, t)
    return {
        "results": results,
        "ports": [
            {
                "name": name,
                "queues": [
                    {
                        "frames": qframes[name][qi],
                        "bytes": qbytes[name][qi],
                        "sent": txq[name][qi],
                        "dropped": dropq[name][qi],
                    }
                    for qi in range(4)
                ],
                "rx_frames": stats[name]["rx_frames"],
                "rx_bytes": stats[name]["rx_bytes"],
                "tx_frames": stats[name]["tx_frames"],
                "tx_bytes": stats[name]["tx_bytes"],
                "collision_frames": stats[name]["collision_frames"],
                "collision_bytes": stats[name]["collision_bytes"],
                "queue_full_frames": stats[name]["queue_full_frames"],
                "queue_full_bytes": stats[name]["queue_full_bytes"],
                "quota_full_frames": stats[name]["quota_full_frames"],
                "quota_full_bytes": stats[name]["quota_full_bytes"],
                "link_down_frames": stats[name]["link_down_frames"],
                "link_down_bytes": stats[name]["link_down_bytes"],
                "pause_frames": stats[name]["pause_frames"],
                "pause_unsupported_frames":
                    stats[name]["pause_unsupported_frames"],
                "pause_duration_ns": pause_ns[name],
                "pfc_frames": stats[name]["pfc_frames"],
                "pfc_unsupported_frames":
                    stats[name]["pfc_unsupported_frames"],
                "pfc_duration_ns": list(pfc_ns[name]),
            }
            for name in by_name
        ],
    }


