import json, subprocess, sys, tempfile, os, zlib

def mac(m): return bytes(int(x,16) for x in m.split(":"))
PAUSE="01:80:c2:00:00:01"; MAC1="00:00:00:00:00:01"; BCAST="ff:ff:ff:ff:ff:ff"

def port(name, pfc=None):
    return {"name":name,"mode":"trunk","pvid":1,"allowed":[1],"untagged":[],
            "rates":[1000],"modes":["full"],"queue_bytes":1000000,
            "flow_control":True,"pfc":[0,1,2,3,4,5,6,7] if pfc is None else pfc}

cfg={"ports":[port("p1"),port("p2")],"age":100,"max_frame":1518,"delay":10,
     "qos":{"map":[0,1,2,3,0,1,2,3],"cap":100000,"mode":"sp",
            "weights":[1,1,1,1],"drop":"tail"}}

def link(t,p): return {"t":t,"port":p,"admin":True,"peer":True,"rates":[1000],"modes":["full"]}
def adv(t): return {"t":t,"advance":True}

def raw(t,p,prio=0,src=MAC1):
    tci=(prio<<13)|1
    head=mac(BCAST)+mac(src)+b"\x81\x00"+tci.to_bytes(2,"big")+(0x0800).to_bytes(2,"big")
    body=head+b"\x00"*46
    fcs=zlib.crc32(body)&0xFFFFFFFF
    return {"t":t,"port":p,"data":(body+fcs.to_bytes(4,"little")).hex()}

def pfc(t,p,ce_bits,quanta):
    # ce_bits: list of enabled prios
    ce=0
    for x in ce_bits: ce|=1<<(7-x)
    body=mac(PAUSE)+mac(MAC1)+b"\x88\x08"+(0x0101).to_bytes(2,"big")+ce.to_bytes(2,"big")
    for q in quanta: body+=q.to_bytes(2,"big")
    body+=b"\x00"*26
    fcs=zlib.crc32(body)&0xFFFFFFFF
    return {"t":t,"port":p,"data":(body+fcs.to_bytes(4,"little")).hex()}

events=[link(0,"p1"),link(0,"p2"),raw(100,"p1",0),raw(110,"p1",3,src="00:00:00:00:00:02"),
        pfc(150,"p2",[0,3],[5,0,0,7,0,0,0,0]),adv(100000)]

with tempfile.TemporaryDirectory() as d:
    cp=os.path.join(d,"c.json"); ep=os.path.join(d,"e.json")
    open(cp,"w").write(json.dumps(cfg)); open(ep,"w").write(json.dumps(events))
    r=subprocess.run([sys.executable,"switch.py","qos-pfc-decode",cp,ep],capture_output=True)
    print("rc",r.returncode, r.stderr.decode())
    out=json.loads(r.stdout)
    for x in out["results"]: print(x)
    print(json.dumps(out["ports"][1],indent=0))
EOF

